/* ===== MINI-GAME: Steady the Flame (first-contact-hope) ===== */
const MG_INSTRUCTOR_LINE = "You hold the flame steady, and those who approach decide whether to trust you.";
const MG = {
  active: false,
  shown_tip: false,
  flame_brightness: 0.5,
  steady_band_center: 0.5,
  nomads: [],
  time: 0,
  won: false,
  failed: false,
  exit_timer: 0
};
function mgInit(st = MG) {
  st.active = false;
  st.shown_tip = false;
  st.flame_brightness = 0.5;
  st.steady_band_center = 0.5;
  st.nomads = [];
  st.time = 0;
  st.won = false;
  st.failed = false;
  st.exit_timer = 0;
  for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    st.nomads.push({
      angle: angle,
      distance: 180,
      committed: true,
      recoiling: false,
      drifting: false
    });
  }
}
function mgStep(st, clicked, dt = 1) {
  if (st.won || st.failed) {
    st.exit_timer += dt;
    return st;
  }
  st.time += dt;
  if (clicked) st.flame_brightness = Math.min(1.0, st.flame_brightness + 0.15);
  st.flame_brightness = Math.max(0, st.flame_brightness - 0.008 * dt);
  st.steady_band_center = 0.5 + Math.sin(st.time * 0.02) * 0.08;
  const steady_min = st.steady_band_center - 0.12;
  const steady_max = st.steady_band_center + 0.12;
  const in_band = st.flame_brightness >= steady_min && st.flame_brightness <= steady_max;
  const too_bright = st.flame_brightness > 0.85;
  const too_dim = st.flame_brightness < 0.25;
  for (const n of st.nomads) {
    n.committed = in_band;
    n.recoiling = too_bright;
    n.drifting = too_dim;
    if (in_band && n.distance > 20) {
      n.distance = Math.max(20, n.distance - 0.6 * dt);
    } else if (too_bright) {
      n.distance = Math.min(180, n.distance + 1.2 * dt);
    } else if (too_dim) {
      n.distance = Math.min(180, n.distance + 0.8 * dt);
    }
  }
  const all_close = st.nomads.every(n => n.distance <= 22);
  if (all_close && in_band) {
    st.won = true;
    st.exit_timer = 0;
  }
  if (too_bright && st.flame_brightness > 0.9) {
    st.failed = true;
    st.exit_timer = 0;
  }
  if (too_dim && st.flame_brightness < 0.15) {
    st.failed = true;
    st.exit_timer = 0;
  }
  return st;
}
if (location.hash.includes('mg')) {
  const _origNewGame = (typeof newGame !== 'undefined') ? newGame : null;
  if (_origNewGame) {
    newGame = function(pole) {
      _origNewGame(pole);
      mgInit(MG);
      MG.active = true;
    };
  }
}

