if (phase === 'play' && !SIM.terminal) {
  const pp = SIM.player_pos;
  const px = pp[0] * CELL + CELL / 2, py = pp[1] * CELL + CELL / 2;
  if (!MG.active && !MG.shown_tip) {
    let grey_near = 0;
    for (const x of SIM.npcs) {
      if (x.tribe === LONER && !x.burn && cheb(x.pos, pp) <= 12) grey_near++;
    }
    if (grey_near >= 6) {
      mgInit(MG);
      MG.active = true;
    }
  }
  if (MG.active) {
    if (!MG.shown_tip) {
      setTip(MG_INSTRUCTOR_LINE);
      MG.shown_tip = true;
    }
    const clicked = this.input.activePointer.isDown && this.input.activePointer.justDown;
    mgStep(MG, clicked, 1);
    this.overlay.fillStyle(0x000000, 0.6);
    this.overlay.fillRect(0, 0, VIEW, VIEW);
    const fb = MG.flame_brightness;
    const flame_y = py - CELL * 1.5;
    if (fb > 0.85) {
      this.overlay.fillStyle(0xffffff, 0.9);
      this.overlay.fillCircle(px, flame_y, 18);
      this.overlay.lineStyle(2, 0xffffff, 0.7);
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * Math.PI * 2 + MG.time * 0.05;
        const lx = px + Math.cos(a) * 25, ly = flame_y + Math.sin(a) * 25;
        this.overlay.lineBetween(px, flame_y, lx, ly);
      }
    } else if (fb < 0.25) {
      const ember_col = 0xff6600;
      this.overlay.fillStyle(ember_col, 0.4 + fb * 0.6);
      this.overlay.fillCircle(px, flame_y, 6 + fb * 8);
    } else {
      const core_col = 0xffdd66;
      this.overlay.fillStyle(core_col, 0.8);
      this.overlay.fillCircle(px, flame_y, 10);
      this.overlay.fillStyle(0xffaa33, 0.4);
      this.overlay.fillCircle(px, flame_y, 16);
    }
    const halo_size = 20 + Math.sin(MG.time * 0.03) * 4;
    this.overlay.fillStyle(0xffdd66, 0.15);
    this.overlay.fillCircle(px, flame_y, halo_size);
    for (const n of MG.nomads) {
      const nx = px + Math.cos(n.angle) * n.distance;
      const ny = py + Math.sin(n.angle) * n.distance;
      let body_col = 0x888888, body_alpha = 1.0;
      if (n.recoiling) {
        body_col = 0x666666;
        body_alpha = 0.5;
      } else if (n.drifting) {
        body_col = 0x555555;
        body_alpha = 0.6;
      } else if (n.committed) {
        body_col = 0x999999;
        body_alpha = 1.0;
      }
      this.overlay.fillStyle(body_col, body_alpha);
      this.overlay.fillCircle(nx, ny, 6);
      this.overlay.fillRect(nx - 3, ny + 6, 6, 8);
    }
    if (MG.won && MG.exit_timer > 30) {
      for (const n of MG.nomads) {
        const nx = px + Math.cos(n.angle) * 25;
        const ny = py + Math.sin(n.angle) * 25;
        const gold_prog = Math.min(1, (MG.exit_timer - 30) / 40);
        this.overlay.fillStyle(0xffaa00, gold_prog);
        this.overlay.fillCircle(nx, ny, 6);
        this.overlay.fillRect(nx - 3, ny + 6, 6, 8);
      }
    }
    if (MG.won && MG.exit_timer > 80) {
      let converted = 0;
      for (const x of SIM.npcs) {
        if (x.tribe === LONER && !x.burn && cheb(x.pos, pp) <= 8) {
          x.v = 8;
          x.ever_nonzero = true;
          converted++;
          if (converted >= 3) break;
        }
      }
      mgInit(MG);
    }
    if (MG.failed && MG.exit_timer > 60) {
      mgInit(MG);
    }
  }
}

